# encoding: utf-8
import json
import os

# Comprehensive question generator adhering to all user constraints:
# 1. Primary & Intermediate math: pure Arabic RTL notation (variables like س, ص; expressions like ٢ س + ٥ = ١٥; fractions as ٤/١٠).
# 2. Abdullah Hamad ONLY for Verbal sections.
# 3. Mohammad Abdullah Jumaa for ALL Math sections.
# 4. Phone symbol 📞 instead of letter ج.
# 5. Covers 7 main tracks & sub-sections with difficulty levels 1 to 5.

def build_questions():
    questions = []
    q_id = 1

    # Helper to add question
    def add_q(track, section, section_ar, topic, question, options, correct_index, explanation, speed_rule, diff=1, has_visual=False, image_url=None):
        nonlocal q_id
        questions.append({
            "id": q_id,
            "track": track,
            "section": section,
            "section_ar": section_ar,
            "topic": topic,
            "question": question,
            "options": options,
            "correct_index": correct_index,
            "explanation": explanation,
            "speed_rule": speed_rule,
            "difficulty": diff,
            "level": diff,
            "has_visual": has_visual,
            "image_url": image_url
        })
        q_id += 1

