        ("إذا كان مع أحمد ٢٥ ريالاً، واشترى دفترين بسعر ٥ ريالات للدفتر الواحد، فكم ريالاً يتبقى معه؟", ["١٥ ريالاً", "٢٠ ريالاً", "١٠ ريالات", "٥ ريالات"], 0, "ثمن الدفترين = ٢ × ٥ = ١٠ ريالات. المتبقي = ٢٥ - ١٠ = ١٥ ريالاً.", "اطرح ثمن المشتريات الإجمالي من المبلغ الأصلي.", 1),
        ("كم يبلغ محيط مربع طول ضلعه ٦ سم؟", ["٢٤ سم", "٣٦ سم", "١٢ سم", "١٨ سم"], 0, "محيط المربع = طول الضلع × ٤ = ٦ × ٤ = ٢٤ سم.", "قانون محيط المربع: الضلع مضروباً في ٤.", 1),
        ("ما باقي قسمة ٢٧ على ٥؟", ["٢", "٣", "١", "٤"], 0, "٢٧ ÷ ٥ = ٥ والمتبقي ٢، لأن ٥ × ٥ = ٢٥.", "أقرب مضاعف لـ ٥ أقل من ٢٧ هو ٢٥، والفرق بينهما ٢.", 1)
