        ("إذا كان ثمن ٣ كتب هو ٤٥ ريالاً، فما ثمن ٧ كتب من نفس النوع؟", ["١٠٥ ريالات", "٩٠ ريالاً", "١٢٠ ريالاً", "٧٥ ريالاً"], 0, "ثمن الكتاب الواحد = ٤٥ ÷ ٣ = ١٥ ريالاً. ثمن ٧ كتب = ٧ × ١٥ = ١٠٥ ريالات.", "سعر التجزئة (١٥) ضرب عدد الكتب الجديد (٧).", 1),
        ("ما القيمة العدديّة للعبارة: | - ٧ | + | ٥ |؟", ["١٢", "٢", "-٢", "-١٢"], 0, "القيمة المطلقة تجعل العدد موجباً دائماً: |-٧| = ٧، |٥| = ٥. الناتج = ٧ + ٥ = ١٢.", "القيمة المطلقة تلغي الإشارة السالبة.", 1),
        ("ما نسبة الأرباح إذا كانت التكلفة ١٠٠ ريال والبيع بـ ١٢٥ ريالاً؟", ["٢٥٪", "٢٠٪", "١٥٪", "٣٠٪"], 0, "مقدار الربح = ١٢٥ - ١٠٠ = ٢٥ ريالاً. نسبة الربح = (٢٥ ÷ ١٠٠) × ١٠٠٪ = ٢٥٪.", "الربح المباشر مقسوماً على التكلفة المائة تعطي النسبة فوراً.", 1)
